fn dot(w: &[f32; N], f: &[f32; N]) -> f32 {
    w.iter().zip(f.iter()).map(|(a, b)| a * b).sum()
}

/// Probabilities of hold, toward, away, sideways, dash for a fighter whose step is ready.
pub fn move_probs(f: &[f32; N]) -> [f32; CLASSES] {
    move_probs_with(&MOVE_WEIGHTS, f)
}

/// As `move_probs`, with the weights given.
pub fn move_probs_with(w: &[[f32; N]; CLASSES], f: &[f32; N]) -> [f32; CLASSES] {
    let mut z = [0.0f32; CLASSES];
    for c in 0..CLASSES {
        z[c] = dot(&w[c], f);
    }
    let m = z.iter().cloned().fold(f32::MIN, f32::max);
    let mut sum = 0.0;
    for c in 0..CLASSES {
        z[c] = (z[c] - m).exp();
        sum += z[c];
    }
    for c in 0..CLASSES {
        z[c] /= sum;
    }
    z
}

/// The probability of yes for one of the yes/no models.
pub fn yes_prob(w: &[f32; N], f: &[f32; N]) -> f32 {
    1.0 / (1.0 + (-dot(w, f)).exp())
}

/// Movement probabilities for fighter `x` straight from a state.
pub fn move_probs_for(e: &Engine, s: &State, x: usize) -> [f32; CLASSES] {
    move_probs(&features(e, s, x))
}


